dijkstra-shortest-paths.solution:
import heapq


def dijkstra(graph, start):
    best = {start: 0}                          # the cheapest cost found so far for each node reached
    heap = [(0, start)]
    while heap:
        cost, node = heapq.heappop(heap)
        if cost > best[node]:
            continue                           # a stale entry: this node was reached more cheaply since
        for neighbour, weight in graph.get(node, ()):
            new_cost = cost + weight
            if neighbour not in best or new_cost < best[neighbour]:
                best[neighbour] = new_cost
                heapq.heappush(heap, (new_cost, neighbour))
    return best

