from collections import deque


def rotting_oranges(grid):
    rows, cols = len(grid), len(grid[0])
    queue = deque()                  # every orange that is rotten right now
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                queue.append((r, c))
            elif grid[r][c] == 1:
                fresh += 1

    minutes = 0
    while queue and fresh:
