def tree_from(levels):
    # [1, 2, 3, None, None, 4, 5]: level by level, left to right, None for a missing child (a missing node has no children listed)
    nodes = [None if v is None else TreeNode(v) for v in levels]
    children = iter(nodes[1:])
    for node in nodes:
        if node is not None:
            node.left = next(children, None)
            node.right = next(children, None)
    return nodes[0] if nodes else None
def levels_of(root):
    # the inverse of tree_from: the tree as its levels, with None for a missing child and no trailing Nones
    out, queue = [], [root]
    for node in queue:
        if node is None:
            out.append(None)
        else:
            out.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
    while out and out[-1] is None:
        out.pop()
    return out
def wreck(root):
    # change the original tree beyond recognition: the text alone must be enough to rebuild it
    stack = [root]
    while stack:
        node = stack.pop()
        if node is not None:
            stack.append(node.left)
            stack.append(node.right)
            node.val, node.left, node.right = -999, None, None
def round_trips(levels):
    original = tree_from(levels)
    expected = levels_of(original)
    text = serialize(original)
    if not isinstance(text, str):
        raise AssertionError(f"serialize must return a str, not {type(text).__name__}")
    wreck(original)
    for attempt in (1, 2):
        rebuilt = deserialize(text)
        if rebuilt is not None and not isinstance(rebuilt, TreeNode):
            raise AssertionError(f"deserialize must return the root TreeNode (or None), not {rebuilt!r}")
        got = levels_of(rebuilt)
        if got != expected:
            raise AssertionError(f"deserialize call {attempt} gave the tree {got[:20]!r} but the tree was {expected[:20]!r} (the text was {text[:60]!r})")
    return True
def leaning(n, side):
    # one path of n nodes, each the left (or right) child of the one before
    levels = [1]
    for value in range(2, n + 1):
        levels += [value, None] if side == "left" else [None, value]
    return levels

serialize-binary-tree.solution:
from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


MISSING = "#"


def serialize(root):
    """Level by level, with a marker for every missing child: 1,2,3,#,#,4,5,#,#,#,#"""
    tokens = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node is None:
            tokens.append(MISSING)
        else:
            tokens.append(str(node.val))
            queue.append(node.left)
            queue.append(node.right)
    return ",".join(tokens)


def deserialize(text):
    tokens = text.split(",")
    if tokens[0] == MISSING:
        return None
    root = TreeNode(int(tokens[0]))
    queue = deque([root])
    position = 1
    while queue:
        node = queue.popleft()               # the next two tokens are this node's children
        if tokens[position] != MISSING:
            node.left = TreeNode(int(tokens[position]))
            queue.append(node.left)
        if tokens[position + 1] != MISSING:
            node.right = TreeNode(int(tokens[position + 1]))
            queue.append(node.right)
        position += 2
    return root

