standard-scaler.solution:
class StandardScaler:
    def __init__(self):
        self.means = None
        self.stds = None

    def fit(self, rows):
        columns = list(zip(*rows))
        self.means = [sum(col) / len(col) for col in columns]
        self.stds = [(sum((v - m) ** 2 for v in col) / len(col)) ** 0.5 for col, m in zip(columns, self.means)]
        return self

    def transform(self, rows):
        if self.means is None:
            raise RuntimeError("call fit before transform")
        return [
            [(v - m) / s if s else 0.0 for v, m, s in zip(row, self.means, self.stds)]
            for row in rows
        ]

    def fit_transform(self, rows):
        return self.fit(rows).transform(rows)

