tests:
from collections import deque
def tree(values):
    """Build a tree from values listed level by level, None for a missing child: [5, 1, 6, None, None, 3, 7]."""
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = deque([root])
    position = 1
    while queue and position < len(values):
        node = queue.popleft()
        for side in ("left", "right"):
            if position < len(values) and values[position] is not None:
                child = TreeNode(values[position])
                setattr(node, side, child)
                queue.append(child)
            position += 1
    return root
def balanced(low, high):
    """A valid search tree holding every integer from low to high, as balanced as it can be."""
    if low > high:
        return None
    middle = (low + high) // 2
    return TreeNode(middle, balanced(low, middle - 1), balanced(middle + 1, high))
far_violation = TreeNode(20, TreeNode(10, TreeNode(5), TreeNode(15, TreeNode(12), TreeNode(25))), TreeNode(30))
broken = balanced(1, 32767)
node = broken.left
while node.right is not None:
    node = node.right
node.val = broken.val + 1

validate-binary-search-tree.solution:
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def is_valid_bst(root):
    def valid(node, low, high):            # every value in this subtree must satisfy low < value < high
        if node is None:
            return True
        if not low < node.val < high:
            return False
        return valid(node.left, low, node.val) and valid(node.right, node.val, high)

    return valid(root, float("-inf"), float("inf"))

